idates c JOIN nddriverinvariant ndi ON ndi.vehicle_id = c.vehicle_id WHERE ndi.start_time >= '2026-11-09'), latest_face AS (SELECT DISTINCT ON (fi.driver_invariant) fi.driver_invariant, fi.driver_id AS vls_driver_id FROM ndfaceimage fi WHERE fi.driver_invariant IN (SELECT driver_invariant FROM dis_windows) ORDER BY fi.driver_invariant, fi.updated_on DESC) SELECT dw.vehicle_id, dw.candidate_driver_id, count(*) AS total_dis, count(*) FILTER (WHERE lf.vls_driver_id > 0) AS assigned_dis, count(*) FILTER (WHERE lf.vls_driver_id IS NULL OR lf.vls_driver_id <= 0) AS unassigned_dis, count(*) FILTER (WHERE lf.vls_driver_id > 0 AND lf.vls_driver_id != dw.candidate_driver_id) AS contradicted_dis FROM dis_windows dw LEFT JOIN latest_face lf ON lf.driver_invariant = dw.driver_invariant GROUP BY dw.vehicle_id, dw.candidate_driver_id ORDER BY total_dis DESC) TO '/Users/swapnilmane/NetraDyne/driver_history_use/data/AN-37739/step_3/step3_preliminary_results.csv' WITH CSV HEADER;
